txt += `Total: **${mios.length}** | Activos: ${activos} | Inactivos: ${inactivos}\n\n`;
if (mios.length === 0) {
  txt += `No tienes hábitos registrados.\n`;
} else {
  mios.forEach(h => { txt += `• ${h.estado==='activo'?'✅':'⏸️'} ${h.nombre} (${h.frecuencia}, ${h.hora_recordatorio})\n`; });
}
txt += `\nEscribe *9* para volver al menú.`;
return [{ json: { chatId, respuesta: txt } }];

const chatId = $('Procesar Lógica y Generar Respuesta (Núcleo)').item.json.chatId;
const user = $('Procesar Lógica y Generar Respuesta (Núcleo)').item.json.telegramUser;
const rows = $input.all().map(i => i.json).filter(c => c.creado_por);
const mias = rows.filter(c => String(c.creado_por) === String(user));

const porEstado = {};
