const chatId = $('Procesar Lógica y Generar Respuesta (Núcleo)').item.json.chatId;

const citas = $('Leer Citas para Productividad Usuarios (Reportes)').all().map(i=>i.json).filter(c => c.creado_por);
const tareas = $('Leer Tareas para Productividad Usuarios (Reportes)').all().map(i=>i.json).filter(t => t.creado_por);
const logs = $('Leer Logs para Productividad Usuarios (Reportes)').all().map(i=>i.json).filter(l => l.telegram_user);
const usuariosInfo = $('Leer Usuarios para Productividad Usuarios (Reportes)').all().map(i=>i.json);

const mapaNombres = {};
usuariosInfo.forEach(u => {
  if (u.telegram_user) mapaNombres[String(u.telegram_user)] = u.nombre;
});

function mostrarComo(id) {
  const nombre = mapaNombres[id];
  if (nombre && nombre.trim().length > 0) {
    const alias = nombre.trim().toLowerCase().replace(/\s+/g, '');
    return '@' + alias;
  }
  return '@' + id;
}

const usuarios = new Set();
citas.forEach(c => usuarios.add(String(c.creado_por)));
tareas.forEach(t => usuarios.add(String(t.creado_por)));
logs.forEach(l => usuarios.add(String(l.telegram_user)));

if (usuarios.size === 0) {
  return [{ json: { chatId, respuesta: `📊 *Reporte de productividad (AgendaBot)*\n\nTodavía no hay datos suficientes para generar un reporte.\n\nEscribe *9* para volver al menú.` } }];
}

const lista = Array.from(usuarios).sort((a,b) => a.localeCompare(b));

const datosPorUsuario = lista.map(u => {
  const misCitas = citas.filter(c => String(c.creado_por) === u);
  const misTareas = tareas.filter(t => String(t.creado_por) === u);
  const misLogs = logs.filter(l => String(l.telegram_user) === u);
  return {
    usuario: u,
    total_citas: misCitas.length,
    citas_completadas: misCitas.filter(c => c.estado === 'completada').length,
    citas_canceladas: misCitas.filter(c => c.estado === 'cancelada').length,
    total_tareas: misTareas.length,
    tareas_completadas: misTareas.filter(t => t.estado === 'completada').length,
    tareas_pendientes: misTareas.filter(t => t.estado === 'pendiente' || t.estado === 'en_progreso').length,
    interacciones: misLogs.length
  };
});

const total_citas_registradas = citas.length;
const total_tareas_registradas = tareas.length;
const total_interacciones_bot = logs.length;
const masActivo = datosPorUsuario.reduce((a,b) => (b.interacciones > a.interacciones ? b : a), datosPorUsuario[0]);
const masActivoDisplay = mostrarComo(masActivo.usuario);

let txt = `📊 *Reporte de productividad (AgendaBot)*\n\n`;
txt += `*Resumen general*\n`;
txt += `- Usuario más activo: ${masActivoDisplay}\n`;
txt += `- Total citas registradas: ${total_citas_registradas}\n`;
txt += `- Total tareas registradas: ${total_tareas_registradas}\n`;
txt += `- Total interacciones con el bot: ${total_interacciones_bot}\n\n`;
txt += `*Detalle por usuario*\n`;

datosPorUsuario.forEach((u, i) => {
  txt += `${i+1}) ${mostrarComo(u.usuario)}\n`;
  txt += `   - Citas: ${u.total_citas} (Completadas: ${u.citas_completadas} | Canceladas: ${u.citas_canceladas})\n`;
  txt += `   - Tareas: ${u.total_tareas} (Hechas: ${u.tareas_completadas} | Pendientes: ${u.tareas_pendientes})\n`;
  txt += `   - Interacciones: ${u.interacciones}\n\n`;
});

txt += `¿Qué deseas hacer ahora?\n1. Volver al menú Reportes\n2. Volver al menú principal`;
return [{ json: { chatId, respuesta: txt } }];
